import asyncio
import logging
from collections.abc import Callable
from time import perf_counter
from typing import TypeVar

from pydantic import BaseModel, ValidationError

from app.clients.openai import OpenAIClient
from app.clients.openrouter import OpenRouterClient
from app.errors import MLErrorCode, MLServiceError, ProviderTimeout
from app.generation import GenerationContext
from app.schemas.common import DialogueMessage

logger = logging.getLogger(__name__)
ResponseT = TypeVar("ResponseT", bound=BaseModel)


class DomainViolation(ValueError):
    """A constraint description generated by code, without untrusted output values."""


_REPAIR_HINTS = {
    "empty_response": "Сформируй ответ целиком. Не оставляй content пустым.",
    "output_truncated": "Сделай формулировки короче, но сохрани все обязательные поля.",
    "json_syntax": "Проверь кавычки, запятые и закрывающие скобки JSON.",
    "root_null": "Верни объект целиком. null допустим только в предусмотренном поле.",
    "root_type": "Объект верхнего уровня обязателен. Не возвращай массив или скаляр.",
    "schema": "Заполни обязательные поля и проверь их типы по схеме.",
    "domain": (
        "Проверь точный набор criterion_id, score по anchors, согласованность status и "
        "evidence. Цитируй только дословный фрагмент реплики кандидата."
    ),
}


def _schema_issue(content: str, error: ValidationError) -> str:
    text = content.strip()
    if text == "null":
        return "root_null"
    errors = error.errors(include_input=False, include_context=False, include_url=False)
    if any(item["type"] == "json_invalid" for item in errors):
        return "json_syntax"
    return "schema" if text.startswith("{") else "root_type"


def build_messages(
    system_prompt: str, trusted_config: str, dialogue: list[DialogueMessage]
) -> list[dict[str, str]]:
    return [
        {"role": "system", "content": system_prompt},
        {"role": "system", "content": f"Trusted task configuration:\n{trusted_config}"},
        *[
            {
                "role": "user" if message.role == "candidate" else "assistant",
                "content": message.content,
            }
            for message in dialogue
        ],
    ]


async def generate_structured(
    *,
    client: OpenRouterClient | OpenAIClient | OpenAIClient,
    context: GenerationContext,
    messages: list[dict[str, str]],
    response_model: type[ResponseT],
    service: str,
    prompt_version: str,
    temperature: float,
    validate: Callable[[ResponseT], None] | None = None,
) -> ResponseT:
    guard = asyncio.timeout(context.remaining())
    try:
        async with guard:
            return await _generate_attempts(
                client=client,
                context=context,
                messages=messages,
                response_model=response_model,
                service=service,
                prompt_version=prompt_version,
                temperature=temperature,
                validate=validate,
            )
    except TimeoutError:
        # An arbitrary application TimeoutError is not our deadline expiring.
        if guard.expired():
            context.error_code = MLErrorCode.TIMEOUT
            raise ProviderTimeout() from None
        raise


async def _generate_attempts(
    *,
    client: OpenRouterClient,
    context: GenerationContext,
    messages: list[dict[str, str]],
    response_model: type[ResponseT],
    service: str,
    prompt_version: str,
    temperature: float,
    validate: Callable[[ResponseT], None] | None,
) -> ResponseT:
    for attempt_number in (1, 2):
        context.remaining()
        started = perf_counter()
        before = len(context.usage.attempts)
        outcome = "failure"
        error_code = None
        repair = False
        validation_issue = None
        try:
            content = await client.complete(
                messages=messages,
                response_model=response_model,
                temperature=temperature,
                context=context,
            )
            context.remaining()
            try:
                result = response_model.model_validate_json(content)
            except ValidationError as exc:
                validation_issue = _schema_issue(content, exc)
                raise MLServiceError(MLErrorCode.SCHEMA_ERROR) from None
            try:
                if validate:
                    validate(result)
            except DomainViolation:
                validation_issue = "domain"
                raise MLServiceError(MLErrorCode.SCHEMA_ERROR) from None
            context.remaining()
            outcome = "success"
            context.error_code = None
            return result
        except asyncio.CancelledError:
            outcome = "cancelled"
            raise
        except MLServiceError as exc:
            error_code = exc.code
            context.error_code = exc.code
            if exc.repairable and validation_issue is None:
                validation_issue = exc.code.value.removeprefix("ML_").lower()
            if not exc.repairable or attempt_number == 2:
                raise
            context.remaining()
            repair = True
            correction = {
                "role": "system",
                "content": (
                    "Предыдущий результат нарушил контракт ответа. "
                    f"Код нарушения: {exc.code.value}. "
                    "Верни новый результат строго по исходной trusted configuration "
                    "и JSON Schema. Соблюдай action/message и status/score/evidence. "
                    "Не добавляй посторонние поля. " + _REPAIR_HINTS.get(validation_issue or "", "")
                ),
            }
            messages = [*messages[:2], correction, *messages[2:]]
        except Exception:
            error_code = MLErrorCode.INTERNAL_ERROR
            raise
        finally:
            metadata = context.usage.attempts[-1] if len(context.usage.attempts) > before else None
            logger.info(
                "service=%s model=%s provider=%s prompt_version=%s correlation_id=%s "
                "attempt=%d provider_attempts=%d latency_ms=%.2f http_status=%s "
                "upstream_status=%s outcome=%s error_code=%s finish_reason=%s "
                "prompt_tokens=%s completion_tokens=%s reasoning_tokens=%s repair=%s "
                "validation_issue=%s",
                service,
                client.model_name,
                client.provider_name,
                prompt_version,
                context.correlation_id,
                len(context.usage.attempts),
                len(context.usage.attempts),
                (perf_counter() - started) * 1000,
                metadata.http_status if metadata else None,
                metadata.upstream_status if metadata else None,
                outcome,
                error_code,
                metadata.finish_reason if metadata else None,
                metadata.prompt_tokens if metadata else None,
                metadata.completion_tokens if metadata else None,
                metadata.reasoning_tokens if metadata else None,
                repair,
                validation_issue,
            )
    raise AssertionError("Unreachable")
